buggy.modulus_as_expr_and_cancel_mod2:
from sympy import Poly, cancel
from sympy.abc import x
N = 10**100
p = Poly(-1, x, modulus=N, symmetric=False)
try:
    val1 = p.as_expr()
except Exception as e:
    val1 = f"as_expr_exception:{type(e).__name__}"

def safe_cancel():
    try:
        return cancel((x**2 - 1)/(x + 1), modulus=2)
    except Exception as e:
        return f"cancel_exception:{type(e).__name__}"

val2 = safe_cancel()
probe('as_expr', val1)
probe('cancel_mod2', val2)

